contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // roll to a block number that is a multiple of 15, driven by the fuzzed seed
        uint256 target = bound(seed, 0, 2**32) * 15;
        vm.roll(target);
        // ensure timestamp strictly increases over pastBlockTime (0 initially)
        vm.warp(1000 + seed % 1000);
        uint256 amount = 10 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.fallback{value: amount}();
        // Reference: at block.number % 15 == 0 the whole balance is paid out to the caller.
        // Buggy mutant keeps the balance (inverted condition) -> this assertion fails.
        assertTrue(address(c).balance == 0);
    }
}

